@section('content')<section class="tutorial-hero"><div class="tutorial-wrap"><a href="{{route('learning.track',$trackSlug)}}">← {{$track['title']}}</a><h1>Laravel Foundations</h1><p>25 practical lessons. Read less, build more, check your understanding immediately.</p><div class="learn-flow"><span>Understand</span>→<span>Run the example</span>→<span>Complete the task</span>→<span>Take the quiz</span></div></div></section><div class="tutorial-wrap course-layout"><aside class="lesson-nav"><strong>Your progress: <span id="score">0</span>/{{count($lessons)}}</strong><div class="progress-shell"><div class="progress-bar" id="progress"></div></div>@foreach($lessons as $lesson)<a href="#lesson-{{$loop->iteration}}">{{$loop->iteration}}. {{$lesson['title']}}</a>@endforeach</aside><main>@foreach($lessons as $lesson)<details class="lesson" id="lesson-{{$loop->iteration}}" {{$loop->first?'open':''}}><summary><span class="lesson-number">{{str_pad($loop->iteration,2,'0',STR_PAD_LEFT)}}</span><span class="lesson-title">{{$lesson['title']}}</span></summary><div class="lesson-body"><div class="concept">{{$lesson['summary']}}</div>@if($loop->iteration===2)<div class="visual-flow"><span>Browser</span>→<span>Route</span>→<span>Middleware</span>→<span>Controller</span>→<span>Service</span>→<span>Model / DB</span>→<span>Response</span></div>@else<div class="visual-flow"><span>Real requirement</span>→<span>Laravel feature</span>→<span>Working code</span>→<span>Test result</span></div>@endif<div class="code-head"><strong>Try this</strong><button class="copy-code" type="button">Copy code</button></div><pre class="code-block"><code>{{$lesson['code']}}</code></pre><div class="challenge"><strong>Hands-on challenge</strong><p>{{$lesson['task']}}</p></div><section class="quiz" data-answer="{{$lesson['answer']}}" data-why="{{$lesson['why']}}" data-lesson="{{$loop->iteration}}"><h3>Quick check</h3><p>Which answer is correct?</p><div class="options">@foreach($lesson['options'] as $option)<button class="option" type="button" data-option="{{$loop->index}}"><b>{{chr(65+$loop->index)}}.</b> {{$option}}</button>@endforeach</div><p class="feedback" aria-live="polite"></p></section></div></details>@endforeach</main></div>@endsection
@push('scripts')<script>(()=>{const key='ascendia_laravel_foundations',done=new Set(JSON.parse(localStorage.getItem(key)||'[]')),score=document.querySelector('#score'),bar=document.querySelector('#progress');function paint(){score.textContent=done.size;bar.style.width=(done.size/{{count($lessons)}}*100)+'%'}paint();document.querySelectorAll('.quiz').forEach(quiz=>{const feedback=quiz.querySelector('.feedback'),answer=Number(quiz.dataset.answer);quiz.querySelectorAll('.option').forEach(button=>button.addEventListener('click',()=>{quiz.querySelectorAll('.option').forEach(x=>{x.disabled=true;if(Number(x.dataset.option)===answer)x.classList.add('correct')});const correct=Number(button.dataset.option)===answer;if(!correct)button.classList.add('wrong');feedback.className='feedback show '+(correct?'good':'bad');feedback.textContent=(correct?'Correct! ':'Not quite. ')+quiz.dataset.why;if(correct){done.add(Number(quiz.dataset.lesson));localStorage.setItem(key,JSON.stringify([...done]));paint()}}))});document.querySelectorAll('.copy-code').forEach(button=>button.addEventListener('click',async()=>{await navigator.clipboard.writeText(button.closest('.lesson-body').querySelector('code').textContent);button.textContent='Copied!';setTimeout(()=>button.textContent='Copy code',1200)}))})();</script>@endpush
